// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load font at module level to guarantee it is ready before frame 0
const { fontFamily: spaceFamily } = loadSpaceGrotesk();



export type ValuePropositionTransitionProps = Record<string, any>;

const ValuePropositionTransition: React.FC<ValuePropositionTransitionProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 6,
  beforeText = "Social Media Manager",
  afterText =
    "Helping small businesses turn social media into consistent leads.",
  beforeColor = "#94a3b8",
  afterColor = "#f8fafc",
  strikeColor = "#ef4444",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Background logic for safety
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timings (Frames)
  const BEFORE_ENTRANCE_START = 10;
  const STRIKE_START = 45;
  const SHIFT_START = 75;
  const AFTER_START = 85;

  // 1. "Before" text entrance (drops in slightly, fades up)
  const beforeEntrance = spring({
    frame: frame - BEFORE_ENTRANCE_START,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // 2. Strikethrough line drawing
  const strikeProgress = spring({
    frame: frame - STRIKE_START,
    fps,
    config: { damping: 16, mass: 0.6 },
  });

  // 3. "Before" text shifting up and fading down to make room
  const beforeShift = spring({
    frame: frame - SHIFT_START,
    fps,
    config: { damping: 16, mass: 1 },
  });

  // Interpolations for "Before" text
  const beforeTopBase = height * 0.5;
  const beforeTopShifted = height * 0.35;
  
  // Calculate dynamic positions and scales
  const currentBeforeTop = interpolate(
    beforeShift,
    [0, 1],
    [beforeTopBase, beforeTopShifted]
  );
  
  const beforeEntranceYOffset = interpolate(
    beforeEntrance,
    [0, 1],
    [40 * s, 0]
  );

  const beforeScale = interpolate(beforeShift, [0, 1], [1, 0.7]);
  
  const beforeOpacityBase = interpolate(beforeEntrance, [0, 1], [0, 1]);
  const beforeOpacity = interpolate(
    beforeShift,
    [0, 1],
    [beforeOpacityBase, 0.4]
  );

  // Split "After" text into words for a staggered cascade effect
  const afterWords = afterText.split(" ");

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: spaceFamily,
        overflow: "hidden",
      }}
    >
      {/* "Before" Text Element */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: currentBeforeTop,
          transform: `translate(-50%, -50%) translateY(${beforeEntranceYOffset}px) scale(${beforeScale})`,
          display: "inline-block",
          textAlign: "center",
          maxWidth: width * 0.9,
          opacity: beforeOpacity,
          transition: "none",
        }}
      >
        <span
          style={{
            position: "relative",
            display: "inline-block",
            fontSize: 90 * s,
            fontWeight: 500,
            color: beforeColor,
            letterSpacing: "-0.02em",
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {beforeText}
          {/* Strikethrough Line */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: 0,
              width: `${strikeProgress * 100}%`,
              height: 12 * s,
              backgroundColor: strikeColor,
              transform: "translateY(-50%)",
              borderRadius: 6 * s,
              transition: "none",
            }}
          />
        </span>
      </div>

      {/* "After" Text Element */}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          alignItems: "center",
          alignContent: "center",
          gap: `${16 * s}px ${24 * s}px`,
          width: width * 0.75,
          position: "absolute",
          left: "50%",
          top: height * 0.6,
          transform: "translate(-50%, -50%)",
          transition: "none",
        }}
      >
        {afterWords.map((word, i) => {
          // Stagger each word's entrance
          const wordStartFrame = AFTER_START + i * 2.5;
          const wordSpring = spring({
            frame: frame - wordStartFrame,
            fps,
            config: { damping: 14, mass: 0.8 },
          });

          const wordY = interpolate(wordSpring, [0, 1], [40 * s, 0]);
          const wordOpacity = interpolate(wordSpring, [0, 1], [0, 1]);

          return (
            <span
              key={i}
              style={{
                display: "inline-block",
                transform: `translateY(${wordY}px)`,
                opacity: wordOpacity,
                fontSize: 85 * s,
                fontWeight: 700,
                color: afterColor,
                lineHeight: 1.15,
                letterSpacing: "-0.02em",
                transition: "none",
              }}
            >
              {word}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ValuePropositionTransition;